<?php

declare(strict_types=1);

namespace Thesis\Amqp;

/**
 * What {@see Channel::queueDeclare()} has learnt about the queue.
 *
 * @api
 */
final readonly class Queue
{
    /**
     * @param non-empty-string $name generated by the server if the declared name was empty
     * @param non-negative-int $messages ready to be delivered, not counting the unacknowledged
     * @param non-negative-int $consumers
     */
    public function __construct(
        public string $name,
        public int $messages,
        public int $consumers,
    ) {}
}
